import heapq


class Helpdesk:
    PRIORITIES = ("normal", "high", "critical")

    def __init__(self) -> None:
        self._customers = {}
        self._tickets = {}
        self._queue = []
        self._next_id = 1

    def add_customer(self, name: str, vip: bool = False) -> None:
        if name in self._customers:
            raise ValueError("Customer already exists")
        self._customers[name] = vip

    def open_ticket(
        self, customer: str, title: str, priority: str = "normal"
    ) -> int:
        if customer not in self._customers:
            raise KeyError(customer)
        if priority not in self.PRIORITIES:
            raise ValueError("Invalid priority")

        ticket_id = self._next_id
        self._next_id += 1
        rank = (
            0 if self._customers[customer] else 1,
            -self.PRIORITIES.index(priority),
            ticket_id,
        )
        self._tickets[ticket_id] = {
            "customer": customer,
            "title": title,
            "priority": priority,
            "rank": rank,
            "state": "queued",
        }
        heapq.heappush(self._queue, rank)
        return ticket_id

    def next_ticket(self) -> int | None:
        while self._queue:
            _, _, ticket_id = heapq.heappop(self._queue)
            ticket = self._tickets[ticket_id]
            if ticket["state"] == "queued":
                ticket["state"] = "taken"
                return ticket_id
        return None

    def close(self, ticket_id: int) -> None:
        self._tickets[ticket_id]["state"] = "closed"

    def reopen(self, ticket_id: int) -> None:
        ticket = self._tickets[ticket_id]
        if ticket["state"] == "closed":
            raise ValueError("A closed ticket cannot be reopened")
        if ticket["state"] == "taken":
            ticket["state"] = "queued"
            heapq.heappush(self._queue, ticket["rank"])
